// Cross-implementation parity harness (roadmap step 4): the web scene graph
// must reproduce the desktop engine's world transforms exactly.
//
// The reference JSONs are generated by tools/dump_world_transforms.py running
// the REAL desktop engine (glyphviz_core.compute_world_transforms) over the
// same CSVs — regenerate them whenever either side's placement math changes.

import { describe, expect, it } from 'vitest'
import * as THREE from 'three'
import { buildScene } from './buildScene'
import { parseGvNodeCsv } from '../gv/nodeCsv'
import { NodeType } from '../gv/types'
import topologyExampleCsv from '../gv/fixtures/topology_example_gv_node.csv?raw'
import topologyReferenceRaw from '../gv/fixtures/topology_example_world_transforms.json?raw'
import worldGridExampleCsv from '../gv/fixtures/world_grid_example_gv_node.csv?raw'
import worldGridReferenceRaw from '../gv/fixtures/world_grid_example_world_transforms.json?raw'

interface ReferenceEntry {
  id: number
  pos: [number, number, number]
  basis: [[number, number, number], [number, number, number], [number, number, number]]
}

interface Reference {
  source_csv: string
  base_scale: number
  nodes: ReferenceEntry[]
}

const TOLERANCE = 1e-6

const FIXTURES: Array<{ name: string; csv: string; reference: Reference }> = [
  {
    name: 'topology example (all 18 topologies)',
    csv: topologyExampleCsv,
    reference: JSON.parse(topologyReferenceRaw) as Reference,
  },
  {
    name: 'world grid example (flat, region, globe, nested)',
    csv: worldGridExampleCsv,
    reference: JSON.parse(worldGridReferenceRaw) as Reference,
  },
]

for (const fixture of FIXTURES) {
  describe(`world-transform parity with the desktop engine: ${fixture.name}`, () => {
    const parsed = parseGvNodeCsv(fixture.csv)
    const { root } = buildScene(parsed.nodes)
    root.updateMatrixWorld(true)
    const reference = fixture.reference
    const byId = new Map(parsed.nodes.map((n) => [n.id, n]))

    it('covers every node in the fixture', () => {
      expect(parsed.errors).toEqual([])
      expect(reference.nodes).toHaveLength(parsed.nodes.length)
      expect(reference.base_scale).toBe(1)
    })

    for (const entry of reference.nodes) {
      it(`node ${entry.id} matches position and basis`, () => {
        const frame = root.getObjectByName(`gv:${entry.id}`)
        expect(frame, `frame for node ${entry.id}`).toBeDefined()

        const pos = new THREE.Vector3().setFromMatrixPosition(frame!.matrixWorld)
        expect(Math.abs(pos.x - entry.pos[0])).toBeLessThan(TOLERANCE)
        expect(Math.abs(pos.y - entry.pos[1])).toBeLessThan(TOLERANCE)
        expect(Math.abs(pos.z - entry.pos[2])).toBeLessThan(TOLERANCE)

        // Desktop world_basis rows/cols vs Three.js column-major Matrix3.
        // A World Grid's desktop world_basis includes its raw scale, but the
        // web frame deliberately carries scale (1,1,1) — the scale reaches
        // children through baked positions and the plate through its draw
        // scale. Re-apply it per column to compare the same composition.
        const basis = new THREE.Matrix3().setFromMatrix4(frame!.matrixWorld)
        const node = byId.get(entry.id)!
        if (node.type === NodeType.WorldGrid) {
          const s = [node.scale.x, node.scale.y, node.scale.z]
          for (let c = 0; c < 3; c++) {
            for (let r = 0; r < 3; r++) basis.elements[c * 3 + r] *= s[c]
          }
        }
        for (let r = 0; r < 3; r++) {
          for (let c = 0; c < 3; c++) {
            const actual = basis.elements[c * 3 + r]
            const expected = entry.basis[r][c]
            expect(
              Math.abs(actual - expected),
              `node ${entry.id} basis[${r}][${c}]: web ${actual} vs desktop ${expected}`,
            ).toBeLessThan(TOLERANCE)
          }
        }
      })
    }
  })
}
